   "codice": "extends RefCounted

class Greeter:
	func greet() -> String:
		return "Hello"

class PoliteGreeter extends Greeter:
	func greet() -> String:
		return super() + " please"

func run() -> String:
	var pg = PoliteGreeter.new()
	return pg.greet()
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`PoliteGreeter` estende `Greeter` e fa l'override del metodo `greet()`. All'interno, chiama `super()` per eseguire la versione del metodo nella classe base (che restituisce "Hello") e aggiunge " please". Il risultato finale è "Hello please"."
