   "codice": "extends RefCounted

class Tool:
	func use() -> String:
		return "generic"

class Sword extends Tool:
	func use() -> String:
		return "slash"
	func sharpen() -> String:
		return "sharp"

func run() -> String:
	var t: Tool = Sword.new()
	var s := t as Sword
	return s.sharpen()
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "La variabile `t` punta a una `Sword` ma è vista come `Tool`. Usando l'operatore di casting `as`, convertiamo la variabile nel tipo specifico `Sword`, permettendoci di chiamare il metodo `sharpen()` che appartiene solo a quella sottoclasse. Restituisce "sharp"."
  },
  {
   "codice": "extends RefCounted

class Tool:
	pass

class Shield:
	pass

func run() -> bool:
	var t: Tool = Tool.new()
	var s = t as Shield
	return s == null
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "Questo è il tranello del casting: `t` è un `Tool` e proviamo a convertirlo in `Shield`, che non ha alcuna parentela di ereditarietà con `Tool`. Quando un cast fallisce, Godot non genera un errore ma restituisce `null`. Di conseguenza, `s == null` è `true`."
